"""Turn a BenchRun into a human-readable markdown report and a machine-readable JSON."""

from __future__ import annotations

import json

from .pipeline import BenchRun, Variant
from .search import Holdout, HoldoutRow, SearchResult

FOOTER = (
    "*Generated by [quantpilot](https://github.com/collins3355-bot/quantpilot)"
    " — quantization autotuning for local models.*"
)


def _hardware_line(hardware: dict) -> str:
    bits = [hardware.get("chip") or hardware.get("machine"), hardware.get("os")]
    if hardware.get("memory_gb"):
        bits.insert(1, f"{hardware['memory_gb']} GB unified memory")
    return ", ".join(str(b) for b in bits if b)


def human_size(size_bytes: int) -> str:
    if size_bytes >= 1024**3:
        return f"{size_bytes / 1024**3:.2f} GB"
    return f"{size_bytes / 1024**2:.0f} MB"


def _tps(value: float | None, sd: float | None = None) -> str:
    if value is None:
        return "—"
    return f"{value:,.0f} ± {sd:,.0f}" if sd is not None else f"{value:,.0f}"


def _row(v: Variant, baseline: Variant, kld: bool, hs: bool) -> str:
    delta_ppl = v.ppl_increase_pct(baseline.ppl)
    delta_size = (v.size_bytes / baseline.size_bytes - 1) * 100
    ci = None if v is baseline else v.ppl_increase_ci(baseline)
    interval = f" [{ci[0]:+.2f}, {ci[1]:+.2f}]" if ci else ""
    cells = [
        v.name,
        human_size(v.size_bytes),
        f"{delta_size:+.0f}%",
        f"{v.ppl:.4f}",
        f"{delta_ppl:+.2f}%{interval}",
    ]
    if kld:
        cells.append(f"{v.mean_kld:.4f}" if v.mean_kld is not None else "—")
        cells.append(f"{v.same_top_pct:.1f}%" if v.same_top_pct is not None else "—")
    if hs:
        cells.append(f"{v.hellaswag_acc:.1f}%" if v.hellaswag_acc is not None else "—")
    cells += [_tps(v.prompt_tps, v.prompt_tps_sd), _tps(v.generate_tps, v.generate_tps_sd)]
    return "| " + " | ".join(cells) + " |"


def render_markdown(run: BenchRun, hardware: dict) -> str:
    rec = run.recommendation()
    kld = run.baseline.mean_kld is not None
    hs = any(v.hellaswag_acc is not None for v in run.all_variants())
    has_ci = any(v.ppl_increase_ci(run.baseline) for v in run.variants)
    has_sd = any(v.generate_tps_sd is not None for v in run.all_variants())
    metric = f"perplexity over {run.chunks} × 512-token chunks of `{run.corpus.name}`"
    if kld:
        metric += ", plus KL divergence of each quant's token distributions vs. baseline"
    if hs:
        metric += ", plus HellaSwag accuracy (task eval)"
    header = ["Variant", "Size", "Δ size", "Perplexity", "Δ PPL"]
    if kld:
        header += ["Mean KLD", "Top-1 agree"]
    if hs:
        header += ["HellaSwag"]
    header += ["Prompt t/s", "Gen t/s"]
    lines = [
        f"# quantpilot report: {run.source.name}",
        "",
        f"Hardware: {_hardware_line(hardware)}",
        f"Engine: {run.engine}",
        f"Quality metric: {metric}",
        f"Quality budget: ≤ {run.budget_pct:g}% perplexity increase vs. baseline",
    ]
    if has_ci:
        lines.append(
            "Δ PPL brackets: ~95% interval, paired chunk by chunk against the baseline "
            "on the same text"
        )
    if has_sd:
        lines.append(
            "Speed: mean ± standard deviation across llama-bench repetitions; between "
            "sessions, thermals and background load can shift it further"
        )
    lines += [
        "",
        "| " + " | ".join(header) + " |",
        "|" + "---|" * len(header),
    ]
    lines += [_row(v, run.baseline, kld, hs) for v in run.all_variants()]
    saved = (1 - rec.size_bytes / run.baseline.size_bytes) * 100
    lines += [
        "",
        "## Recommendation",
        "",
        f"**{rec.name}** — {human_size(rec.size_bytes)} "
        f"({saved:.0f}% smaller than baseline) at "
        f"{rec.ppl_increase_pct(run.baseline.ppl):+.2f}% perplexity, "
        f"inside the {run.budget_pct:g}% budget.",
    ]
    rec_ci = None if rec is run.baseline else rec.ppl_increase_ci(run.baseline)
    if rec_ci and rec_ci[1] > run.budget_pct:
        lines += [
            "",
            f"Borderline: the 95% interval reaches {rec_ci[1]:+.2f}%, past the budget. "
            f"Rerun with more `--chunks` to tighten it before relying on this pick.",
        ]
    lines += ["", f"Artifact: `{rec.path}`", "", "---", FOOTER]
    return "\n".join(lines) + "\n"


def holdout_verdict(row: HoldoutRow, budget_pct: float) -> str:
    """'holds', 'borderline' (point inside, interval crosses) or 'fails'."""
    if row.dppl_pct > budget_pct:
        return "fails"
    if row.ci and row.ci[1] > budget_pct:
        return "borderline"
    return "holds"


def _render_holdout(result: SearchResult, h: Holdout) -> list[str]:
    budget = f"{result.budget_pct:g}%"
    lines = [
        "",
        "## Held-out check",
        "",
        f"The search never saw `{h.corpus.name}`, so these numbers show whether the recipe "
        f"generalizes (baseline PPL {h.baseline_ppl:.4f}). Intervals are ~95%, paired "
        f"chunk by chunk against the baseline.",
        "",
        "| Variant | Size | Δ PPL vs. baseline | 95% interval |",
        "|---|---|---|---|",
    ]
    for label, row in (
        (f"uniform {result.base}", h.base),
        (f"uniform {result.bump}", h.bump),
        ("recipe", h.recipe),
    ):
        ci = f"{row.ci[0]:+.2f}% to {row.ci[1]:+.2f}%" if row.ci else "—"
        lines.append(f"| {label} | {human_size(row.size_bytes)} | {row.dppl_pct:+.2f}% | {ci} |")

    verdict = holdout_verdict(h.recipe, result.budget_pct)
    if verdict == "holds":
        text = (
            f"**Holds on held-out text:** the recipe stays inside the {budget} budget "
            f"({h.recipe.dppl_pct:+.2f}%)."
        )
    elif verdict == "borderline":
        text = (
            f"**Borderline on held-out text:** {h.recipe.dppl_pct:+.2f}% on the point "
            f"estimate, but the 95% interval reaches {h.recipe.ci[1]:+.2f}%. Rerun with "
            f"more `--chunks` before relying on it."
        )
    else:
        text = (
            f"**Does not hold on held-out text:** {h.recipe.dppl_pct:+.2f}% against the "
            f"{budget} budget. The recipe fit the tuning text better than text in general; "
            f"prefer uniform {result.bump}, or tune on more text (`--chunks`)."
        )
    lines += ["", text]

    if h.recipe_vs_bump:
        pct, lo, hi = h.recipe_vs_bump
        saved = h.bump.size_bytes - h.recipe.size_bytes
        if hi < 0:
            quality = "better quality"
        elif lo > 0:
            quality = "worse quality"
        else:
            quality = "no measurable quality difference"
        lines += [
            "",
            f"Recipe vs. uniform {result.bump}: {human_size(abs(saved))} "
            f"{'smaller' if saved > 0 else 'larger'}, perplexity {pct:+.2f}% "
            f"(95% interval {lo:+.2f}% to {hi:+.2f}%): {quality}.",
        ]
    return lines


def render_search(result: SearchResult, hardware: dict, ladder: dict | None = None) -> str:
    base_dppl = (result.base_ppl - result.baseline_ppl) / result.baseline_ppl * 100
    tuned_on = result.tune_corpus or result.corpus
    lines = [
        f"# quantpilot search report: {result.source.name}",
        "",
        f"Hardware: {_hardware_line(hardware)}",
        f"Recipe space: base {result.base}, bump {result.bump}, per tensor class",
        f"Tuning metric: perplexity over {result.chunks} × 512-token chunks of `{tuned_on.name}`",
        f"Quality budget: ≤ {result.budget_pct:g}% PPL increase vs. full-precision baseline "
        f"(PPL {result.baseline_ppl:.4f} on the tuning text)",
        "",
        f"Uniform {result.base}: {human_size(result.base_size)}, "
        f"PPL {result.base_ppl:.4f} ({base_dppl:+.2f}% vs. baseline)",
        "",
        "## Sensitivity probes (ranked by quality recovered per GB)",
        "",
        "| Class | Size added | PPL | PPL recovered | Recovery / GB |",
        "|---|---|---|---|---|",
    ]
    for p in result.probes:
        lines.append(
            f"| {p.cls} | +{p.size_delta / 1024**2:.0f} MB | {p.ppl:.4f} "
            f"| {p.ppl_recovered:+.4f} | {p.recovery_per_gb:.3f} |"
        )

    if result.failed:
        lines += [
            "",
            f"Probes skipped (crashed — likely tensor shapes incompatible with "
            f"{result.bump}): {', '.join(result.failed)}",
        ]

    lines += ["", "## Composition", "", "| Step | Recipe | Size | Δ PPL vs. baseline |", "|---|---|---|---|"]
    for i, s in enumerate(result.steps, start=1):
        recipe = f"{result.base} + {{{', '.join(s.classes)}}}→{result.bump}"
        mark = " ✅" if s.dppl_pct <= result.budget_pct else ""
        lines.append(
            f"| {i} | {recipe} | {human_size(s.size_bytes)} | {s.dppl_pct:+.2f}%{mark} |"
        )

    lines += ["", "## Result", ""]
    if result.met_budget and result.steps:
        final = result.steps[-1]
        lines.append(
            f"**Met the {result.budget_pct:g}% budget on the tuning text** at "
            f"{human_size(final.size_bytes)} ({final.dppl_pct:+.2f}% PPL) with "
            f"{len(final.classes)} class bump(s): {', '.join(final.classes)}."
        )
    else:
        lines.append(
            f"**Did not meet the {result.budget_pct:g}% budget** within this recipe space — "
            f"consider a higher base type or a larger bump."
        )

    if result.holdout is not None:
        lines += _render_holdout(result, result.holdout)

    if ladder:
        within = [
            v
            for v in ladder["variants"][1:]
            if v["ppl_increase_pct"] <= result.budget_pct
        ]
        if within and result.met_budget and result.steps:
            best_uniform = min(within, key=lambda v: v["size_bytes"])
            saved = best_uniform["size_bytes"] - result.steps[-1].size_bytes
            caveat = (
                " These bench numbers come from different text; the held-out check "
                "above is the fair comparison."
                if result.holdout is not None
                else ""
            )
            lines += [
                "",
                f"Uniform ladder comparison: the smallest preset inside the budget was "
                f"**{best_uniform['name']}** at {human_size(best_uniform['size_bytes'])} "
                f"({best_uniform['ppl_increase_pct']:+.2f}%). The composed recipe is "
                f"{human_size(abs(saved))} {'smaller' if saved > 0 else 'larger'}.{caveat}",
            ]
    if result.final_path is not None:
        lines += ["", f"Artifact: `{result.final_path}`"]
    if result.recipe_command():
        lines += ["", "Reproduce:", "", "```", result.recipe_command(), "```"]
    lines += ["", "---", FOOTER]
    return "\n".join(lines) + "\n"


def _holdout_json(h: Holdout | None) -> dict | None:
    if h is None:
        return None

    def row(r: HoldoutRow) -> dict:
        return {
            "size_bytes": r.size_bytes,
            "ppl": r.ppl,
            "dppl_pct": r.dppl_pct,
            "ci_pct": list(r.ci) if r.ci else None,
        }

    return {
        "corpus": str(h.corpus),
        "baseline_ppl": h.baseline_ppl,
        "uniform_base": row(h.base),
        "uniform_bump": row(h.bump),
        "recipe": row(h.recipe),
        "recipe_vs_bump_pct": list(h.recipe_vs_bump) if h.recipe_vs_bump else None,
    }


def search_to_json(result: SearchResult, hardware: dict) -> str:
    payload = {
        "source": str(result.source),
        "engine": "llama.cpp",
        "base": result.base,
        "bump": result.bump,
        "budget_pct": result.budget_pct,
        "chunks": result.chunks,
        "corpus": str(result.corpus),
        "tune_corpus": str(result.tune_corpus) if result.tune_corpus else None,
        "hardware": hardware,
        "baseline_ppl": result.baseline_ppl,
        "base_ppl": result.base_ppl,
        "base_size_bytes": result.base_size,
        "probes": [
            {
                "class": p.cls,
                "size_delta_bytes": p.size_delta,
                "ppl": p.ppl,
                "ppl_recovered": p.ppl_recovered,
                "recovery_per_gb": p.recovery_per_gb,
            }
            for p in result.probes
        ],
        "steps": [
            {
                "classes": s.classes,
                "size_bytes": s.size_bytes,
                "ppl": s.ppl,
                "dppl_pct": s.dppl_pct,
            }
            for s in result.steps
        ],
        "met_budget": result.met_budget,
        "holdout": _holdout_json(result.holdout),
        "failed_probes": result.failed,
        "final_path": str(result.final_path) if result.final_path else None,
        "recipe_command": result.recipe_command(),
    }
    return json.dumps(payload, indent=2) + "\n"


def to_json(run: BenchRun, hardware: dict) -> str:
    rec = run.recommendation()
    variants = []
    for v in run.all_variants():
        ci = None if v is run.baseline else v.ppl_increase_ci(run.baseline)
        variants.append(
            {
                "name": v.name,
                "path": str(v.path),
                "size_bytes": v.size_bytes,
                "ppl": v.ppl,
                "ppl_err": v.ppl_err,
                "ppl_increase_pct": v.ppl_increase_pct(run.baseline.ppl),
                "ppl_increase_ci_pct": list(ci) if ci else None,
                "mean_kld": v.mean_kld,
                "same_top_pct": v.same_top_pct,
                "hellaswag_acc": v.hellaswag_acc,
                "prompt_tps": v.prompt_tps,
                "generate_tps": v.generate_tps,
                "prompt_tps_sd": v.prompt_tps_sd,
                "generate_tps_sd": v.generate_tps_sd,
                "chunk_nll": v.chunk_nll,
            }
        )
    payload = {
        "source": str(run.source),
        "engine": run.engine,
        "corpus": str(run.corpus),
        "chunks": run.chunks,
        "budget_pct": run.budget_pct,
        "hardware": hardware,
        "variants": variants,
        "recommendation": rec.name,
    }
    return json.dumps(payload, indent=2) + "\n"
